package am.ik.yavi.core;

import am.ik.yavi.fn.Combining2;
import am.ik.yavi.fn.Function2;
import am.ik.yavi.fn.Validation;
import org.jspecify.annotations.Nullable;

/**
 * A {@link Combining2} of {@link Validated} results, whose {@link #apply(Function2)}
 * returns a {@link Validated}.
 *
 * <p>
 * It is returned by {@link Validated#combine(Validation)}.
 *
 * <p>
 * Generated by <a href=
 * "https://github.com/making/yavi/blob/develop/scripts/generate-applicative.sh">generate-applicative.sh</a>.
 *
 * @param <T1> the value type of validation 1
 * @param <T2> the value type of validation 2
 * @since 0.18.0
 */
public class ValidatedCombining2<T1 extends @Nullable Object, T2 extends @Nullable Object>
		extends Combining2<ConstraintViolation, T1, T2> {

	/**
	 * Creates a combination of the given validation results.
	 * @param v1 validation 1
	 * @param v2 validation 2
	 */
	public ValidatedCombining2(Validated<T1> v1, Validated<T2> v2) {
		super(v1, v2);
	}

	/**
	 * Applies the given function to the validated values if all of the combined
	 * validations are successful. Otherwise the violations of all failed validations are
	 * accumulated in the order of the combined validations and the function is not
	 * invoked.
	 * @param f the function that receives the validated values
	 * @param <R> the type of the result
	 * @return the successful result of the function or the accumulated violations
	 */
	@Override
	public <R extends @Nullable Object> Validated<R> apply(Function2<T1, T2, R> f) {
		return Validated.of(super.apply(f));
	}

	/**
	 * Returns a combination that also includes the given validation. The validation is
	 * appended after the existing ones, which determines the order of accumulated
	 * violations.
	 * @param v3 the validation to add
	 * @param <T3> the value type of the added validation
	 * @return the combination of 3 validations
	 */
	@Override
	public <T3 extends @Nullable Object> ValidatedCombining3<T1, T2, T3> combine(
			Validation<ConstraintViolation, T3> v3) {
		return new ValidatedCombining3<>(Validated.of(v1), Validated.of(v2), Validated.of(v3));
	}

}
